def drive(me, enemy, arena):
    if not me.can_drive:
        return None

    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = sqrt(dx * dx + dy * dy)
    b = bearing_to(enemy.x, enemy.y)
    radial = sqrt(me.x * me.x + me.y * me.y)

    if dist > 4.0:
        base = 5.0
    elif dist > 2.2:
        base = 4.0
    else:
        base = 3.0

    if radial > 5.15:
        b = bearing_to(0.0, 0.0)
        base = 2.2

    if abs(b) > 100.0:
        base = 0.0

    want = 4.0 * b - 0.7 * me.turn_rate
    diff = clampv(want / 180.0, -1.0, 1.0)
    left = clampv(base - diff, -1.0, 1.0)
    right = clampv(base + diff, -1.0, 1.0)
    return (left, right)


def weapons(me, enemy, arena):
    front = me.weapons.get("front")
    if front is None:
        return None

    if (me.inverted or me.on_side) and not me.righting and not me.airborne:
        last = me.memory.get("sr_try", -100.0)
        if arena.time - last > 3.0:
            me.memory["sr_try"] = arena.time
            return [self_right()]
        return None

    cmds = []
    if front.get("health", 0.0) > 0.0:
        cmds.append(spin("front", 2350))

    back = me.weapons.get("back")
    if back is not None and back.get("type") == "lifter":
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        dist = sqrt(dx * dx + dy * dy)
        b = bearing_to(enemy.x, enemy.y)

        eligible = (
            dist < 1.85
            and abs(b) > 115.0
            and not enemy.airborne
            and not enemy.inverted
            and not enemy.on_side
            and not enemy.righting
        )

        state = back.get("state", "down")
        if state == "down":
            if eligible and back.get("cooldown", 0.0) <= 0.0:
                me.memory["lift_t"] = arena.time
                cmds.append(lift("back"))
        elif state == "up":
            engaged = back.get("engaged", False)
            started = me.memory.get("lift_t", arena.time)
            if engaged or arena.time - started < 1.2:
                cmds.append(lift("back"))
            else:
                cmds.append(lower("back"))

    return cmds

