def drive(me, enemy, arena):
    if not me.can_drive:
        return None

    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = sqrt(dx * dx + dy * dy)

    if dist < 1.25:
        tx = enemy.x
        ty = enemy.y
    else:
        enemy_speed_sq = enemy.vx * enemy.vx + enemy.vy * enemy.vy
        along = dx * enemy.vx + dy * enemy.vy
        den = 49.0 - enemy_speed_sq

        if den > 0.1:
            lead = (along + sqrt(along * along + den * dist * dist)) / den
        else:
            lead = dist / 7.0

        lead = clampv(lead, 0.0, 1.8)
        tx = enemy.x + enemy.vx * lead
        ty = enemy.y + enemy.vy * lead

    target_radius = sqrt(tx * tx + ty * ty)
    if target_radius > 5.3:
        scale = 5.3 / target_radius
        tx = tx * scale
        ty = ty * scale

    b = bearing_to(tx, ty)
    wanted = 2.8 * b - 0.8 * me.turn_rate
    turn = clampv(wanted / 90.0, -1.0, 1.0)

    left = clampv(1.0 - turn, -1.0, 1.0)
    right = clampv(1.0 + turn, -1.0, 1.0)

    hot = max(me.drive_left_temperature, me.drive_right_temperature)
    if hot >= 145.0:
        return (0.0, 0.0)
    if hot >= 125.0:
        left = left * 0.65
        right = right * 0.65

    return (left, right)


