def steer_to(me, tx, ty, amount):
    b = bearing_to(tx, ty)
    turn = clampv((2.4 * b - 0.75 * me.turn_rate) / 90.0, -1.0, 1.0)
    left = clampv(amount * (1.0 - turn), -1.0, 1.0)
    right = clampv(amount * (1.0 + turn), -1.0, 1.0)
    return left, right


