    if hot >= 165.0:
        return 0.0, 0.0
    if hot >= 145.0:
        return left * 0.35, right * 0.35
    if hot >= 125.0:
        return left * 0.65, right * 0.65
    return left, right


def drive(me, enemy, arena):
    if not me.can_drive:
        return None

    dx = enemy.x - me.x
    dy = enemy.y - me.y
    dist = max(0.001, sqrt(dx * dx + dy * dy))
    b = bearing_to(enemy.x, enemy.y)
    last_flip = me.memory.get("last_flip", -100.0)
    since_flip = arena.time - last_flip

    enemy_bad = (enemy.airborne or enemy.inverted or enemy.on_side or
                 enemy.righting or enemy.lifted)

    if enemy_bad:
        start = me.memory.get("enemy_bad_start", arena.time)
        me.memory["enemy_bad_start"] = start

        if arena.time - start < 0.65 and dist < 2.6 and abs(b) < 70.0:
            cmd = (-0.85, -0.85)
        else:
            tx = me.x + (me.x - enemy.x) / dist * 2.2
            ty = me.y + (me.y - enemy.y) / dist * 2.2
            radius = sqrt(tx * tx + ty * ty)
            if radius > 5.2:
                scale = 5.2 / radius
                tx = tx * scale
                ty = ty * scale
            cmd = steer_to(me, tx, ty, 0.85)

    elif me.held or me.lifted:
        if abs(b) < 75.0:
            cmd = (-0.9, -0.9)
        else:
            tx = me.x + (me.x - enemy.x) / dist * 1.5
            ty = me.y + (me.y - enemy.y) / dist * 1.5
            cmd = steer_to(me, tx, ty, 0.85)

    elif since_flip < 1.15 and dist < 1.5:
        if abs(b) < 70.0:
            cmd = (-0.72, -0.72)
        else:
            tx = me.x + (me.x - enemy.x) / dist * 1.3
            ty = me.y + (me.y - enemy.y) / dist * 1.3
            cmd = steer_to(me, tx, ty, 0.75)

    else:
        front = me.weapons.get("front", {})
        ready = front.get("ready", False)
        if dist < 1.28 and not ready:
            if abs(b) < 70.0:
                cmd = (-0.65, -0.65)
            else:
                tx = me.x + (me.x - enemy.x) / dist
                ty = me.y + (me.y - enemy.y) / dist
                cmd = steer_to(me, tx, ty, 0.7)
        else:
            tx = enemy.x
            ty = enemy.y
            radius = sqrt(tx * tx + ty * ty)
            if radius > 5.75:
                scale = 5.75 / radius
                tx = tx * scale
                ty = ty * scale
            cmd = steer_to(me, tx, ty, 0.95)

    return limit_heat(me, cmd[0], cmd[1])


